void addEdge(int u, int v) {
    Edge *e = (Edge*)malloc(sizeof(Edge));
    e->to = v;
    e->next = graph[u];
    graph[u] = e;
}

void dfs1(int u, int p) {
    parent[u] = p;
    double sum = 0;
    int children = 0;
    for (Edge *e = graph[u]; e; e = e->next) {
        int v = e->to;
        if (v == p) continue;
        dfs1(v, u);
        sum += downExp[v];
        children++;
    }
    if (children == 0) {
        downExp[u] = 0; // leaf
    } else {
        downExp[u] = 1 + sum / children;
    }
}

void dfs2(int u, int p) {
    // Compute sum of downExp of all neighbors
    double total = 0;
    int cnt = 0;
    for (Edge *e = graph[u]; e; e = e->next) {
        int v = e->to;
        if (v == p) {
            total += upExp[u];
        } else {
            total += downExp[v];
        }
        cnt++;
    }
    for (Edge *e = graph[u]; e; e = e->next) {
        int v = e->to;
        if (v == p) continue;
        double otherSum = total - downExp[v];
        int otherCnt = cnt - 1;
        if (otherCnt == 0) {
            upExp[v] = 1;
        } else {
            upExp[v] = 1 + otherSum / otherCnt;
        }
        dfs2(v, u);
    }
    // compute answer for u
    if (cnt == 0) {
        ans[u] = 0;
    } else {
        ans[u] = 1 + total / cnt;
    }
}

