        order[ordsz++] = v;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            if (to == parent[v]) continue;
            parent[to] = v;
            stack[top++] = to;
        }
    }

    double *down = (double *)calloc(N + 1, sizeof(double));
    for (int i = N - 1; i >= 0; i--) {
        int v = order[i];
        if (v == 1) {
            if (deg[v] == 0) down[v] = 0.0;
            else {
                double sum = 0.0;
                for (int e = head[v]; e != -1; e = edges[e].next) {
                    int to = edges[e].to;
                    if (to == parent[v]) continue;
                    sum += down[to];
                }
                down[v] = 1.0 + sum / deg[v];
            }
        } else {
            int child_cnt = deg[v] - 1;
            if (child_cnt == 0) {
                down[v] = 0.0;
            } else {
