def solve():
    input = sys.stdin.readline
    N = int(input())
    g = [[] for _ in range(N)]
    for _ in range(N - 1):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        g[u].append(v)
        g[v].append(u)

    # dp1[u] = expected turns starting from u, moving only into its subtree
    dp1 = [0.0] * N
    parent = [-1] * N
    order = [0]
    for v in order:
        for to in g[v]:
            if to != parent[v]:
                parent[to] = v
                order.append(to)
    for v in reversed(order):
        children = [to for to in g[v] if to != parent[v]]
        if not children:
            dp1[v] = 0.0
        else:
            dp1[v] = 1.0 + sum(dp1[c] for c in children) / len(children)

    # reroot dp
    dp = [0.0] * N
    dp[0] = dp1[0]

    for v in order:
        children = [to for to in g[v] if to != parent[v]]
        deg = len(g[v])
        if deg == 0:
            continue
        sum_all = sum(dp1[c] for c in children)
        if parent[v] != -1:
            sum_all += dp[v]  # dp[v] already includes contribution from parent side
        for c in children:
            # remove c's contribution from v's expected value
            if deg == 1:
                dp[c] = 0.0
            else:
                dp[c] = 1.0 + (sum_all - dp1[c]) / (deg - 1)
            # dp[c] now is the expected value from c if we came from v

    out = '\n'.join(f"{dp[i]:.10f}" for i in range(N))
    sys.stdout.write(out)

