        g[v].push_back(u);
    }

    vector<double> down(N, 0.0), ans(N, 0.0);

    // First DFS:
    // down[v] = expected number of moves starting from v,
    // assuming parent of v is already visited (so cannot move to parent).
    function<void(int,int)> dfs1 = [&](int v, int p) {
        double sum = 0.0;
        int cnt = 0;
        for (int to : g[v]) {
            if (to == p) continue;
            dfs1(to, v);
            sum += down[to];
            cnt++;
        }
        if (cnt == 0) down[v] = 0.0;
        else down[v] = 1.0 + sum / cnt;
    };
    dfs1(0, -1);

    // Second DFS:
    // up[v] = expected value from the parent side when parent is available as a move.
    // We directly compute ans[v].
    function<void(int,int,double)> dfs2 = [&](int v, int p, double upVal) {
        int deg = (int)g[v].size();

        double total = 0.0;
        for (int to : g[v]) {
            if (to == p) total += upVal;
            else total += down[to];
        }

        if (deg == 0) ans[v] = 0.0;
        else ans[v] = 1.0 + total / deg;

        for (int to : g[v]) {
            if (to == p) continue;

            int options_at_v_excluding_to = deg - 1;
            double nextUp;
            if (options_at_v_excluding_to == 0) {
                nextUp = 0.0;
            } else {
                double sum_excluding_to = total - down[to];
                nextUp = 1.0 + sum_excluding_to / options_at_v_excluding_to;
            }
            dfs2(to, v, nextUp);
        }
    };
    dfs2(0, -1, 0.0);

