        }
        System.out.print(sb);
    }

    static void dfs1(int u, int p) {
        int childCount = 0;
        double sum = 0;
        for (int v : adj[u]) {
            if (v == p) continue;
            dfs1(v, u);
            childCount++;
            sum += dp[v];
        }
        if (childCount == 0) {
            dp[u] = 0;
        } else {
            dp[u] = 1 + sum / childCount;
        }
    }

    static void dfs2(int u, int p) {
        int deg = adj[u].size();
        if (p == -1) {
            // root
            ans[u] = dp[u];
        } else {
            // compute expected from u when coming from parent
            double sumChildren = 0;
            for (int v : adj[u]) {
                if (v == p) continue;
                sumChildren += dp[v];
            }
            // expected from u when parent is visited
            double upVal;
            if (deg == 1) {
                // only parent is neighbor -> stuck
                upVal = 0;
            } else {
                // from u, available moves: parent side value + children
                double parentContrib = ans[p] * adj[p].size() - (1 + dp[u]);
                // Actually careful: ans[p] = 1 + (1/deg(p)) * sum over neighbors of expected from that neighbor with p visited
                // We want expected from u if we came from p: that's computed as: 
                // from p, available moves = deg(p) - 1 (excluding u)
                // sum of (1+dp[neighbor]) for all neighbors except u gives deg(p)*ans[p] - (1+dp[u])
                double sumOthers = deg * ans[u] - (1 + dp[u]); // but ans[u] not yet computed? Actually we compute differently.
                // Let's compute it directly:
                double sumNeighborsExceptU = 0;
                for (int w : adj[p]) {
                    if (w == u) continue;
                    if (w == adj[p].get(0)) continue; // dummy, we'll just sum properly
                }
                // Better approach: from p, with u visited:
                // expected steps from p = 1 + (1/(deg(p)-1)) * (sum over neighbors != u of (1+expected_from_that_neighbor))
                // But we have ans[p] = 1 + (1/deg(p)) * sum over all neighbors (1+expected_from_neighbor)
                // So sum over all neighbors (1+expected) = deg(p) * (ans[p] - 1)
                // Then sum over neighbors != u = deg(p)*(ans[p]-1) - (1+dp[u])
                double totalSum = deg * (ans[p] - 1);
                double sumOthers2 = totalSum - (1 + dp[u]);
                if (deg - 1 == 0) {
                    upVal = 0;
                } else {
                    upVal = 1 + sumOthers2 / (deg - 1);
                }
            }

            // now ans[u] = 1 + (1/deg) * ( upVal + sum over children (1+dp[child]) )
            double childSum = 0;
            for (int v : adj[u]) {
                if (v == p) continue;
                childSum += (1 + dp[v]);
            }
            ans[u] = 1 + (upVal + childSum) / deg;
        }

        for (int v : adj[u]) {
            if (v == p) continue;
            dfs2(v, u);
        }
    }
}

