            double ans=k==0?0:1+S/k;
            sb.append(ans).append("\n");}
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int N;
    static ArrayList<Integer>[] g;
    static double[] down;
    static double[] ans;
    static int[] parent;
    static int[] childCount;
    static double[] sumChildren;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();
        g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();
        for (int i = 0; i < N - 1; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            g[u].add(v);
            g[v].add(u);
        }

        down = new double[N];
        ans = new double[N];
        parent = new int[N];
        childCount = new int[N];
        sumChildren = new double[N];
        Arrays.fill(parent, -2);

        buildRootedTreeAndDown();
        reroot();

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) {
            sb.append(ans[i]).append('\n');
        }
        System.out.print(sb.toString());
    }

    static void buildRootedTreeAndDown() {
        int[] order = new int[N];
        int sz = 0;
        int[] stack = new int[N];
        int top = 0;
        stack[top++] = 0;
        parent[0] = -1;

        while (top > 0) {
            int v = stack[--top];
            order[sz++] = v;
            for (int to : g[v]) {
                if (to == parent[v]) continue;
                parent[to] = v;
                stack[top++] = to;
            }
        }

        for (int i = N - 1; i >= 0; i--) {
            int v = order[i];
            double sum = 0.0;
            int cnt = 0;
            for (int to : g[v]) {
                if (to == parent[v]) continue;
                sum += down[to];
                cnt++;
            }
            childCount[v] = cnt;
            sumChildren[v] = sum;
            if (cnt == 0) down[v] = 0.0;
            else down[v] = 1.0 + sum / cnt;
        }
    }

    static void reroot() {
        int[] stack = new int[N];
        int top = 0;
        stack[top++] = 0;
        ans[0] = down[0];

        while (top > 0) {
            int v = stack[--top];

            for (int to : g[v]) {
                if (to == parent[v]) continue;

                int degTo = g[to].size();
                double upFromParent;
                if (degTo == 1) {
                    upFromParent = 0.0;
                } else {
                    double sumExcludingTo = ans[v] * g[v].size() - 1.0 - down[to];
                    // More directly:
                    // At child 'to', after moving to parent v, from v there are deg(v)-1 choices excluding 'to'.
                    // Expected remaining steps from v without going back to 'to':
                    // if deg(v)-1 == 0 => impossible since then to would be root's only neighbor and degTo==1 handled leaf only.
                    int choicesAtV = g[v].size() - 1;
                    double expectedFromV;
                    if (choicesAtV == 0) expectedFromV = 0.0;
                    else expectedFromV = 1.0 + (sumChildren[v] - down[to] + parentContribution(v)) / choicesAtV;
                    upFromParent = expectedFromV;
                }

                // Actually expected starting from 'to':
                // choose uniformly among neighbors; one is parent with value upFromParent, others are children with down[]
                double total = upFromParent + (sumChildren[to]);
                ans[to] = 1.0 + total / degTo;

                stack[top++] = to;
            }
        }
    }

    static double parentContribution(int v) {
        if (parent[v] == -1) return 0.0;
        // If from v we move to its parent, then from parent[v] we cannot return to v.
        // This value is exactly the "up" value already encoded through ans[v]:
        // ans[v] = 1 + ( parentContribution(v) + sumChildren[v] ) / deg(v)
        // So parentContribution(v) = deg(v) * (ans[v] - 1) - sumChildren[v]
        return g[v].size() * (ans[v] - 1.0) - sumChildren[v];
    }
}
